def solve(words, width):
    """Greedy word wrap.
    Pack words into lines separated by single spaces.
    No line exceeds *width* unless a single word is longer than width.
    Return list of line strings.
    """
    if not words:
        return []
    lines = []
    current = ''
    for w in words:
        if not current:
            # start new line with word (even if longer than width)
            current = w
        else:
            # try to add with a space
            if len(current) + 1 + len(w) <= width:
                current += ' ' + w
            else:
                lines.append(current)
                current = w
    lines.append(current)
    return lines

