def solve(n, edges):
    """Return shortest path weight from 0 to n-1 in an undirected weighted graph.
    n: number of nodes (0..n-1). edges: list of [a,b,w] with w > 0.
    If n==1, distance is 0. If node n-1 unreachable, return -1.
    """
    import heapq
    if n <= 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append((b, w))
            adj[b].append((a, w))
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]  # (dist, node)
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1

