def solve(a: str, b: str) -> int:
    """Compute Levenshtein edit distance between strings a and b."""
    m, n = len(a), len(b)
    # Initialize DP for empty a
    dp = list(range(n + 1))
    for i in range(1, m + 1):
        previous = dp[:]  # copy of previous row
        dp[0] = i
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[j] = previous[j - 1]
            else:
                dp[j] = 1 + min(previous[j],    # deletion
                               dp[j - 1],      # insertion
                               previous[j - 1])  # substitution
    return dp[n]

