def solve(coins, amount):
    """Return the minimum number of coins needed to make up ``amount`` using unlimited
    supply of the given ``coins``. If impossible, return -1.
    """
    # Edge case
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values to avoid infinite loops
    filtered = [c for c in coins if c > 0]
    if not filtered:
        return -1
    # Initialize DP array with a value larger than any possible answer
    INF = amount + 1  # because at most amount coins of denomination 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in filtered:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1
